// GENERATED by tools/make-join-variant.py from hh.ts. Do not edit.
// Hoisted HTML: routes, ids, htmx verbs and schema-bound forms (prototype, research only).
//
// A route definition is the one place the protocol is written: method, path, params, query,
// body schema, what a success answers (a page, one fragment id, nothing) and what a 422
// answers. Views and handlers derive from it, and every attribute string that does not
// depend on request data is built once, when the route or the schema is defined.

import { Attrs, Html, Id, Url, esc, html, TemplateError, type Rooted } from "./hh-join.ts";

// ── ids ─────────────────────────────────────────────────────────────────────

type Camel<S extends string> = S extends `${infer A}-${infer B}` ? `${A}${Capitalize<Camel<B>>}` : S;
const ID_OK = /^[a-z][a-z0-9-]*$/;

export function defineIds<const T extends readonly string[]>(...names: T): { readonly [N in T[number] as Camel<N>]: Id<N> } {
  const out: Record<string, Id> = {};
  for (const name of names) {
    if (!ID_OK.test(name)) throw new TemplateError(`an id is lowercase kebab-case; got "${name}"`);
    out[name.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase())] = new Id(name);
  }
  return out as never;
}

export const MAIN = new Id("main");

// ── schema (stands in for TypeBox in the prototype) ─────────────────────────

type StringSchema = { readonly kind: "string"; readonly minLength?: number; readonly maxLength?: number; readonly format?: "email" | "url" };
type NumberSchema = { readonly kind: "number"; readonly min?: number; readonly max?: number };
type EnumSchema<V extends string = string> = { readonly kind: "enum"; readonly values: readonly V[] };
type FieldSchema = StringSchema | NumberSchema | EnumSchema;
export type ObjectSchema<F extends Record<string, FieldSchema> = Record<string, FieldSchema>> = { readonly kind: "object"; readonly fields: F; readonly optional: ReadonlySet<string> };

export const t = {
  string: (o: Omit<StringSchema, "kind"> = {}): StringSchema => ({ kind: "string", ...o }),
  number: (o: Omit<NumberSchema, "kind"> = {}): NumberSchema => ({ kind: "number", ...o }),
  enum: <const V extends string>(values: readonly V[]): EnumSchema<V> => ({ kind: "enum", values }),
  object: <F extends Record<string, FieldSchema>>(fields: F, o: { optional?: readonly (keyof F & string)[] } = {}): ObjectSchema<F> => ({
    kind: "object",
    fields,
    optional: new Set(o.optional ?? []),
  }),
};

type FieldValue<F> = F extends EnumSchema<infer V> ? V : F extends NumberSchema ? number : string;
export type Static<S> = S extends { readonly fields: infer F } ? { [K in keyof F]: FieldValue<F[K]> } : never;

export type FormState<T> = { readonly values?: { readonly [K in keyof T]?: unknown }; readonly errors?: { readonly [K in keyof T]?: string } };

export function validate<S extends ObjectSchema>(schema: S, raw: Record<string, unknown>): { ok: true; value: Static<S> } | { ok: false; state: FormState<Static<S>> } {
  const errors: Record<string, string> = {};
  const value: Record<string, unknown> = {};
  for (const name in schema.fields) {
    const f = schema.fields[name]!;
    const v = raw[name];
    const text = typeof v === "string" ? v.trim() : v === undefined || v === null ? "" : String(v);
    if (text === "") {
      if (!schema.optional.has(name)) errors[name] = "Required";
      continue;
    }
    if (f.kind === "string") {
      if (f.minLength !== undefined && text.length < f.minLength) errors[name] = `At least ${f.minLength} characters`;
      else if (f.maxLength !== undefined && text.length > f.maxLength) errors[name] = `At most ${f.maxLength} characters`;
      else if (f.format === "email" && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(text)) errors[name] = "Not an email address";
      value[name] = text;
    } else if (f.kind === "number") {
      const n = Number(text);
      if (!Number.isFinite(n)) errors[name] = "Not a number";
      else if (f.min !== undefined && n < f.min) errors[name] = `At least ${f.min}`;
      else if (f.max !== undefined && n > f.max) errors[name] = `At most ${f.max}`;
      value[name] = n;
    } else {
      if (!f.values.includes(text)) errors[name] = "Not one of the options";
      value[name] = text;
    }
  }
  for (const _ in errors) return { ok: false, state: { values: raw, errors } as FormState<Static<S>> };
  return { ok: true, value: value as Static<S> };
}

// ── routes ──────────────────────────────────────────────────────────────────

type Method = "get" | "post" | "put" | "patch" | "delete";
type ParamKind = "string" | "number" | readonly string[];
type QueryKind = "string" | "number" | "boolean";

export type RouteDef = {
  readonly method?: Method;
  readonly path?: string;
  readonly params?: Readonly<Record<string, ParamKind>>;
  readonly query?: Readonly<Record<string, QueryKind>>;
  readonly body?: ObjectSchema;
  /** A success answers this one fragment. Omitted: a page. */
  readonly fragment?: Id;
  /** A 422 answers this fragment (the form region). */
  readonly invalid?: Id;
  /** A success answers no markup (JSON, bytes, an off-origin redirect). */
  readonly machine?: true;
};

type Value<K> = K extends "number" ? number : K extends "boolean" ? boolean : K extends readonly (infer U)[] ? U : string;
type ParamsOf<D> = D extends { readonly params: infer P } ? { readonly [K in keyof P]: Value<P[K]> } : {};
type QueryOf<D> = D extends { readonly query: infer Q } ? { readonly [K in keyof Q]?: Value<Q[K]> | null } : {};
type BodyOf<D> = D extends { readonly body: infer S } ? Static<S> : undefined;
type ArgsOf<D> = ParamsOf<D> & QueryOf<D>;
type FragmentOf<D> = D extends { readonly fragment: Id<infer N> } ? N : never;

type Spec = {
  readonly def: RouteDef;
  readonly method: Method;
  readonly segments: readonly string[]; // path split at its params
  readonly paramNames: readonly string[];
  readonly staticHref: string | null; // no params: the URL without a query, built once
  readonly tail: string; // target and swap from the stance, built once
  readonly formTail: string; // tail plus the 422 routing, built once
};

const TAIL_PAGE = ` hx-target="#main" hx-swap="outerMorph show:top" hx-push-url="true"`;

export class Route<D extends RouteDef = RouteDef> extends Url {
  readonly spec: Spec;
  declare readonly def: D;
  constructor(href: string, spec: Spec) {
    super(href);
    this.spec = spec;
  }
  override extra(tag: string, attr: string, flags: number): string {
    const spec = this.spec;
    const url = esc(this.href);
    if (attr === "href") return tag === "a" && spec.def.machine !== true ? ` hx-get="${url}"` + spec.tail : "";
    if (attr === "action") {
      const method = flags === 1 ? "" : ` method="${spec.method === "get" ? "get" : "post"}"`;
      return method + ` hx-${spec.method}="${url}"` + spec.formTail;
    }
    if (attr.startsWith("hx-")) {
      if (attr !== "hx-" + spec.method) throw new TemplateError(`${attr} got a ${spec.method.toUpperCase()} route: write hx-${spec.method}`);
      return spec.tail;
    }
    return "";
  }
}

type RouteFn<D extends RouteDef> = ({} extends ArgsOf<D> ? (args?: ArgsOf<D>) => Route<D> : (args: ArgsOf<D>) => Route<D>) & { readonly spec: Spec; readonly def: D };

export function defineRoutes<const R extends Record<string, RouteDef>>(prefix: string, defs: R): { readonly [K in keyof R]: RouteFn<R[K]> } {
  const out: Record<string, unknown> = {};
  for (const key in defs) {
    const def = defs[key]!;
    const full = (prefix + (def.path ?? "")).replace(/(.)\/$/, "$1");
    const segments = full.split(/:[A-Za-z0-9_]+/);
    const paramNames = [...full.matchAll(/:([A-Za-z0-9_]+)/g)].map((m) => m[1]!);
    for (const p of paramNames) if (def.params?.[p] === undefined) throw new TemplateError(`route ${key}: ":${p}" has no entry in params`);
    const tail = def.machine === true ? ` hx-swap="none"` : def.fragment !== undefined ? ` hx-target="#${def.fragment.name}" hx-swap="outerMorph"` : TAIL_PAGE;
    const spec: Spec = {
      def,
      method: def.method ?? "get",
      segments,
      paramNames,
      staticHref: paramNames.length === 0 ? full : null,
      tail,
      formTail: tail + (def.invalid !== undefined ? ` hx-status:422="swap:outerMorph target:#${def.invalid.name} push:false"` : ""),
    };
    const queryNames = def.query === undefined ? [] : Object.keys(def.query);
    const fn = (args?: Record<string, unknown>): Route => {
      let href = spec.staticHref ?? segments[0]!;
      if (spec.staticHref === null) {
        for (let i = 0; i < paramNames.length; i++) {
          const v = args?.[paramNames[i]!];
          if (v === undefined || v === null || (typeof v === "number" && !Number.isFinite(v))) throw new TemplateError(`route ${key}: param "${paramNames[i]}" is missing`);
          href += encodeURIComponent(String(v)) + segments[i + 1]!;
        }
      }
      if (args !== undefined) {
        let sep = "?";
        for (let i = 0; i < queryNames.length; i++) {
          const v = args[queryNames[i]!];
          if (v === undefined || v === null || v === "") continue;
          href += sep + queryNames[i] + "=" + encodeURIComponent(String(v));
          sep = "&";
        }
      }
      return new Route(href, spec);
    };
    out[key] = Object.assign(fn, { spec, def });
  }
  return out as never;
}

// ── htmx verbs: the patterns whose protocol is easy to get wrong ─────────────

type FragmentRoute = Route<RouteDef & { readonly fragment: Id }>;
type Every = `${number}s`;

export const hx = {
  /** A debounced filter: fires after typing stops, the newest request wins. */
  search(route: Route, delayMs = 300): Attrs {
    return new Attrs(` hx-get="${esc(route.href)}" hx-trigger="input changed delay:${delayMs}ms, search" hx-sync="this:replace" hx-include="this"` + route.spec.tail);
  },
  /** Self-refresh while work runs. It stops when the fragment renders without it. */
  poll(route: FragmentRoute, every: Every = "2s"): Attrs {
    return new Attrs(` hx-get="${esc(route.href)}" hx-trigger="every ${every}" hx-target="this" hx-swap="outerHTML"`);
  },
  /** A region fetched after the page answers. */
  defer(route: FragmentRoute): Attrs {
    return new Attrs(` hx-get="${esc(route.href)}" hx-trigger="load" hx-target="this" hx-swap="outerHTML" hx-sync="this:replace" aria-busy="true"`);
  },
};

// ── forms bound to the route's body schema ──────────────────────────────────

class FieldAttrs extends Attrs {
  readonly input: string;
  constructor(base: string, input: string) {
    super(base);
    this.input = input;
  }
  override on(tag: string): string {
    return tag === "input" ? this.s + this.input : this.s;
  }
}

type FieldStatics = { readonly base: string; readonly type: string };
const fieldStatics = new WeakMap<ObjectSchema, Record<string, FieldStatics>>();

function staticsFor(schema: ObjectSchema): Record<string, FieldStatics> {
  let s = fieldStatics.get(schema);
  if (s !== undefined) return s;
  s = {};
  for (const name in schema.fields) {
    const f = schema.fields[name]!;
    let base = ` id="${name}" name="${name}"`;
    if (!schema.optional.has(name)) base += " required";
    let type = "";
    if (f.kind === "string") {
      if (f.minLength !== undefined) base += ` minlength="${f.minLength}"`;
      if (f.maxLength !== undefined) base += ` maxlength="${f.maxLength}"`;
      type = ` type="${f.format ?? "text"}"`;
    } else if (f.kind === "number") {
      if (f.min !== undefined) type += ` min="${f.min}"`;
      if (f.max !== undefined) type += ` max="${f.max}"`;
      type = ` type="number"` + type;
    }
    s[name] = { base, type };
  }
  fieldStatics.set(schema, s);
  return s;
}

export type FieldError = { readonly id: string; readonly message: string };

export class Form<T> {
  readonly #schema: ObjectSchema;
  readonly #statics: Record<string, FieldStatics>;
  readonly #state: FormState<T>;
  constructor(schema: ObjectSchema, state: FormState<T>) {
    this.#schema = schema;
    this.#statics = staticsFor(schema);
    this.#state = state;
  }
  /** id, name, type and constraints from the schema; value and error wiring from the state. */
  field(name: keyof T & string): Attrs {
    const st = this.#statics[name]!;
    const error = this.#state.errors?.[name];
    const v = this.#state.values?.[name];
    const invalid = error === undefined ? "" : ` aria-invalid="true" aria-describedby="${name}-error"`;
    return new FieldAttrs(st.base + invalid, st.type + (v === undefined || v === null ? "" : ` value="${esc(String(v))}"`));
  }
  label(name: keyof T & string): Attrs {
    return new Attrs(` for="${name}"`);
  }
  error(name: keyof T & string): FieldError | undefined {
    const message = this.#state.errors?.[name];
    return message === undefined ? undefined : { id: `${name}-error`, message };
  }
  /** The current value as text: the content of a <textarea>. */
  value(name: keyof T & string): string {
    const v = this.#state.values?.[name];
    return v === undefined || v === null ? "" : String(v);
  }
  /** <option> elements for an enum field; the labels object must cover every value. */
  options<K extends keyof T & string>(name: K, labels: { readonly [V in T[K] & string]: string }): Html {
    const f = this.#schema.fields[name]!;
    const current = this.#state.values?.[name];
    let s = "";
    if (f.kind === "enum") {
      for (const v of f.values) s += html`<option value="${v}" selected="${v === current}">${(labels as Record<string, string>)[v]}</option>`.s;
    }
    return new Html(s);
  }
}

export function form<D extends RouteDef & { readonly body: ObjectSchema }>(route: { readonly def: D }, state: FormState<Static<D["body"]>> = {}): Form<Static<D["body"]>> {
  return new Form(route.def.body, state);
}

// ── handlers: what each route may answer follows from its definition ────────

export type Page = { readonly kind: "page"; readonly title: string; readonly body: Html };
export type Redirect = { readonly kind: "redirect"; readonly to: string };
export type Invalid<T> = { readonly kind: "invalid"; readonly errors: { readonly [K in keyof T]?: string } };

export const page = (title: string, body: Html): Page => ({ kind: "page", title, body });
export const redirect = (to: Route): Redirect => ({ kind: "redirect", to: to.href });
export const invalid = <T>(errors: { readonly [K in keyof T]?: string }): Invalid<T> => ({ kind: "invalid", errors });

type Ctx<D> = { readonly params: ParamsOf<D>; readonly query: QueryOf<D>; readonly body: BodyOf<D> };
type Success<D> = [FragmentOf<D>] extends [never] ? Page | Redirect : Rooted<FragmentOf<D>>;
type Entry<D> = D extends { readonly invalid: Id<infer N>; readonly body: infer S }
  ? {
      /** The form region. The framework calls it with the rejected values and errors and answers 422. */
      readonly form: (state: FormState<Static<S>>) => Rooted<N>;
      readonly valid: (ctx: Ctx<D>) => Promise<Success<D> | Invalid<Static<S>>> | Success<D> | Invalid<Static<S>>;
    }
  : (ctx: Ctx<D>) => Promise<Success<D>> | Success<D>;

type DefOf<F> = F extends { readonly def: infer D } ? D : never;

export function controller<R extends Record<string, { readonly def: RouteDef }>>(routes: R, entries: { readonly [K in keyof R]: Entry<DefOf<R[K]>> }) {
  return { routes, entries };
}

export type Answer = { status: number; html?: string; location?: string; title?: string };

/** Prototype dispatcher: enough to exercise the three screens without an HTTP server. */
export async function dispatch(
  ctl: { routes: Record<string, { readonly def: RouteDef }>; entries: Record<string, unknown> },
  name: string,
  req: { params?: Record<string, unknown>; query?: Record<string, unknown>; body?: Record<string, unknown> } = {},
): Promise<Answer> {
  const def = ctl.routes[name]!.def;
  const entry = ctl.entries[name] as
    | ((ctx: unknown) => unknown)
    | { form: (s: FormState<Record<string, unknown>>) => Html; valid: (ctx: unknown) => unknown };
  const ctx = { params: req.params ?? {}, query: req.query ?? {}, body: req.body as unknown };
  let result: unknown;
  if (typeof entry === "function") {
    result = await entry(ctx);
  } else {
    const checked = validate(def.body!, req.body ?? {});
    if (!checked.ok) return { status: 422, html: entry.form(checked.state).s };
    ctx.body = checked.value;
    result = await entry.valid(ctx);
    if ((result as Invalid<unknown>).kind === "invalid") {
      return { status: 422, html: entry.form({ values: req.body ?? {}, errors: (result as Invalid<Record<string, unknown>>).errors }).s };
    }
  }
  if (result instanceof Html) return { status: 200, html: result.s };
  const r = result as Page | Redirect;
  if (r.kind === "redirect") return { status: 303, location: r.to };
  return { status: 200, title: r.title, html: r.body.s };
}
